package local.generalsmc.client;
import local.generalsmc.*;
import local.generalsmc.nativebridge.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.*;
import net.minecraft.core.BlockPos;
import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
/** Targeted real-client release UX, without unrelated combat/NPC waiting. */
final class NativeReleaseUxBench {
 static int stage,age;static CompletableFuture<?> work;static NativeProfiles.Profile original;static final BlockPos FAR=new BlockPos(8192,64,8192);static boolean unloaded;static long teleportStarted;
 static void next(int s){stage=s;age=0;GeneralsMod.LOG.info("Release details case {}",s);}
 static void click(Minecraft mc,String label){NativeSetupBench.click(MenuScreens.active(mc.screen),label);}
 static void marker(String kind,BlockPos pos){NativeNetworkClient.request(kind,j->{j.addProperty("x",pos.getX());j.addProperty("y",pos.getY());j.addProperty("z",pos.getZ());});}
 static boolean tick(Minecraft mc,List<String> checks)throws Exception{
  age++;if(age>1200)throw new IllegalStateException("Release details timeout "+stage+": "+NativeNetworkClient.error);
  if(stage==0){original=NativeProfiles.active();var parent=new GeneralsSetupScreen(null);mc.setScreen(new NativeProfilesScreen(parent));click(mc,original.name());if(MenuScreens.active(mc.screen)!=parent)throw new IllegalStateException("Selecting a valid game opened its editor");checks.add("Selecting a valid game returns directly to setup; editing is a separate action");
   var missing=new NativeProfiles.Profile(UUID.randomUUID().toString(),"Missing fixture",original.game()+"-missing",original.base(),"",false,original.factions(),original.colors(),original.checkedAt(),original.engineHash());
   Files.writeString(NativeProfiles.root().resolve("profiles.json"),GeneralsMod.JSON.toJson(new NativeProfiles.Registry(1,original.id(),List.of(original,missing))));mc.setScreen(new NativeProfilesScreen(parent));click(mc,"Missing fixture");if(!(MenuScreens.active(mc.screen) instanceof ProfileStatusScreen s)||!s.missing)throw new IllegalStateException("Missing game did not offer repair");NativeSetupBench.bounds(MenuScreens.active(mc.screen));Screenshot.grab(mc.gameDirectory,"111-missing-game.png",mc.getMainRenderTarget(),c->{});click(mc,"Удалить подключение");((net.minecraft.client.gui.components.Button)MenuScreens.active(mc.screen).children().stream().filter(w->w instanceof net.minecraft.client.gui.components.Button).findFirst().orElseThrow()).onPress();NativeProfiles.select(original.id());if(NativeProfiles.read().profiles().size()!=1)throw new IllegalStateException("Connection removal failed");checks.add("A missing installation offers locate/remove; confirmed removal keeps the installed game untouched");
   mc.setScreen(new GeneralsGuide(parent));for(int i=0;i<3;i++)click(mc,"Далее");NativeSetupBench.bounds(MenuScreens.active(mc.screen));Screenshot.grab(mc.gameDirectory,"112-guide-markers.png",mc.getMainRenderTarget(),c->{});click(mc,"Готово");checks.add("The guide can be replayed from setup and all four pages fit the compact GUI");
   work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);if(l.getChunkSource().getChunkNow(FAR.getX()>>4,FAR.getZ()>>4)!=null)throw new IllegalStateException("Far fixture unexpectedly loaded");if(WorldSiteStore.get(l).contains(NativeReleaseBench.SUPPLY))WorldSiteStore.get(l).annotate(NativeReleaseBench.SUPPLY,"","");WorldSiteStore.get(l).putStart(FAR,2,"",2,-1);},mc.getSingleplayerServer());next(1);
  }else if(stage==1&&work.isDone()){work.join();mc.setScreen(new MarkerFinderScreen(null));next(2);
  }else if(stage==2&&NativeNetworkClient.markers!=null&&age>5){marker("marker_info",NativeReleaseBench.SUPPLY);next(3);
  }else if(stage==3&&MenuScreens.active(mc.screen) instanceof MarkerDetailsScreen s){s.name.setValue("Village supplies");s.note.setValue("Reserve for village defence");click(mc,"Сохранить");next(4);
  }else if(stage==4&&MenuScreens.active(mc.screen) instanceof MarkerDetailsScreen s&&!s.status.isEmpty()&&age>10){work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);var store=WorldSiteStore.get(l);var a=store.annotation(NativeReleaseBench.SUPPLY);if(!a.name().equals("Village supplies")||!a.note().equals("Reserve for village defence"))throw new IllegalStateException("Marker label not saved");var nbt=store.save(new net.minecraft.nbt.CompoundTag(),l.registryAccess());if(!nbt.getList("annotations",10).getCompound(0).getString("note").equals(a.note()))throw new IllegalStateException("Marker annotation not serialized");},mc.getSingleplayerServer());NativeSetupBench.bounds(s);Screenshot.grab(mc.gameDirectory,"113-marker-details.png",mc.getMainRenderTarget(),c->{});click(mc,"Назад");next(5);
  }else if(stage==5&&work.isDone()&&MenuScreens.active(mc.screen) instanceof MarkerFinderScreen){work.join();checks.add("Marker name and note save through authenticated Fabric requests and appear in persisted NBT and the finder");marker("marker_info",FAR);next(6);
  }else if(stage==6&&MenuScreens.active(mc.screen) instanceof MarkerDetailsScreen){click(mc,"Параметры армии");click(mc,"Участник: игрок");click(mc,"Сохранить");next(7);
  }else if(stage==7&&MenuScreens.active(mc.screen) instanceof MarkerDetailsScreen s&&s.details.start().difficulty()==0){checks.add("A distant saved start can be edited into an NPC from the same marker details menu");work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);unloaded=l.getChunkSource().getChunkNow(FAR.getX()>>4,FAR.getZ()>>4)==null;},mc.getSingleplayerServer());next(8);
  }else if(stage==8&&work.isDone()){work.join();if(!unloaded)throw new IllegalStateException("Teleport fixture is already loaded");teleportStarted=System.nanoTime();click(mc,"Телепортироваться");next(9);
  }else if(stage==9&&mc.player.position().distanceTo(FAR.getCenter())<20&&age>5){checks.add("Teleport loads a previously unloaded marker chunk asynchronously and arrives at a collision-free safe position");mc.options.guiScale().set(2);mc.resizeDisplay();Screenshot.grab(mc.gameDirectory,"114-marker-remote-arrival.png",mc.getMainRenderTarget(),c->{});click(mc,"Удалить маркер…");((net.minecraft.client.gui.components.Button)MenuScreens.active(mc.screen).children().stream().filter(w->w instanceof net.minecraft.client.gui.components.Button).findFirst().orElseThrow()).onPress();next(10);
  }else if(stage==10&&MenuScreens.active(mc.screen) instanceof MarkerFinderScreen&&NativeNetworkClient.markers.points().stream().noneMatch(p->p.x()==FAR.getX())){work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);if(WorldSiteStore.get(l).contains(FAR))throw new IllegalStateException("Deleted marker persisted");},mc.getSingleplayerServer());next(11);
  }else if(stage==11&&work.isDone()){work.join();checks.add("Confirmed deletion immediately after teleport removes a saved marker and refreshes the finder");mc.setScreen(new NativeLobbyScreen(null));NativeNetworkClient.request("rules_get");next(12);
  }else if(stage==12&&age>10){click(mc,"Правила");if(!(MenuScreens.active(mc.screen) instanceof WorldSettingsScreen))throw new IllegalStateException("Rules not available from lobby");NativeSetupBench.bounds(MenuScreens.active(mc.screen));Screenshot.grab(mc.gameDirectory,"115-lobby-rules.png",mc.getMainRenderTarget(),c->{});checks.add("Rules are directly accessible from the skirmish lobby");next(13);}
  else if(stage==13&&age>12){Screenshot.grab(mc.gameDirectory,"115-lobby-rules.png",mc.getMainRenderTarget(),c->{});mc.setScreen(new GeneralsGuide(new GeneralsSetupScreen(null)));next(14);}
  else if(stage==14){if(age%5==0&&age%35>2)Screenshot.grab(mc.gameDirectory,String.format("guide-%03d.png",age/5),mc.getMainRenderTarget(),c->{});if(age%35==0){if(((GeneralsGuide)MenuScreens.active(mc.screen)).step<3)click(mc,"Далее");else{click(mc,"Готово");mc.setScreen(new MarkerFinderScreen(null));next(15);}}}
  else if(stage==15&&age>15){Screenshot.grab(mc.gameDirectory,"116-marker-finder.png",mc.getMainRenderTarget(),c->{});marker("marker_info",NativeReleaseBench.SUPPLY);next(16);}
  else if(stage==16&&MenuScreens.active(mc.screen) instanceof MarkerDetailsScreen s){if(age%5==0)Screenshot.grab(mc.gameDirectory,String.format("marker-%03d.png",age/5),mc.getMainRenderTarget(),c->{});if(age==15)s.note.setValue("Village defence");if(age==35)click(mc,"Сохранить");if(age>60){Screenshot.grab(mc.gameDirectory,"113-marker-details.png",mc.getMainRenderTarget(),c->{});mc.setScreen(new GeneralsSetupScreen(null));click(mc,"Свободная игра");((NativeLaunchScreen)MenuScreens.active(mc.screen)).faction="FactionChinaTankGeneral";click(mc,"Начать");next(17);}}
  else if(stage==17&&age>100&&NativeWorldView.current!=null&&NativeWorldView.current.scene!=null&&NativeWorldView.current.state.frame()>100){if(NativeWorldView.current.state.objects().stream().noneMatch(a->a.template().equals("Tank_ChinaCommandCenter")))throw new IllegalStateException("Wrong logo fixture base");Screenshot.grab(mc.gameDirectory,"117-command-centre-alpha.png",mc.getMainRenderTarget(),c->{});checks.add("Actual original Tank command-centre runs and renders in Minecraft with the exported two-stage alpha material");return true;}
  return false;
 }
}

